-- ============================================================================
-- Crowne Plaza Hotel Management System - Multi-Year Historical Ledger Archive
-- Comprehensive Synthetic Benchmark Dataset (2020 - 2025) for Load Testing
-- ============================================================================
CREATE SCHEMA IF NOT EXISTS historical_archive;
CREATE TABLE IF NOT EXISTS historical_archive.legacy_stay_records (
    legacy_id SERIAL PRIMARY KEY,
    guest_name VARCHAR(100),
    room_number VARCHAR(10),
    room_type VARCHAR(50),
    check_in DATE,
    check_out DATE,
    tariff_per_night NUMERIC(10, 2),
    total_paid NUMERIC(10, 2),
    payment_type VARCHAR(30),
    notes TEXT
);

